export function MainLogo({ className = "", drawOnMount = false, drawOnHover = false, drawDuration = 3 }) {
  const reduceMotion = useReducedMotion();
  const id = useId().replace(/:/g, "");

  const mainGradient = `${id}-main`;
  const crossGradient = `${id}-cross`;
  const small1Gradient = `${id}-small-1`;
  const small2Gradient = `${id}-small-2`;
  const small3Gradient = `${id}-small-3`;
  const centerGradient = `${id}-center`;

  const gradients = {
    main: `url(#${mainGradient})`,
    cross: `url(#${crossGradient})`,
    small1: `url(#${small1Gradient})`,
    small2: `url(#${small2Gradient})`,
    small3: `url(#${small3Gradient})`,
    center: `url(#${centerGradient})`,
  };

  const shouldAnimate = !reduceMotion && (drawOnMount || drawOnHover);

  const maskVariants = {
    hidden: {
      pathLength: 0,
      opacity: 0,
    },

    visible: {
      pathLength: 1,
      opacity: 1,
    },

    hover: {
      pathLength: [0, 1],
      opacity: [0, 1],
    },
  };
  return (
    <motion.svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="240 190 600 600"
      className={className}
      initial={drawOnMount && !reduceMotion ? "hidden" : "visible"}
      animate="visible"
      whileHover={drawOnHover && !reduceMotion ? "hover" : undefined}
      aria-hidden="true"
    >
      <defs>
        {/* ORİJİNAL GRADIENTLER */}

        <linearGradient id={mainGradient} x1="276.39" y1="487.53" x2="669.89" y2="487.53" gradientUnits="userSpaceOnUse">
          <stop offset=".16" stopColor="#870b18" />
          <stop offset=".74" stopColor="#ae0f17" />
        </linearGradient>

        <linearGradient id={crossGradient} x1="340.01" y1="325.87" x2="795.6" y2="325.87" href={`#${mainGradient}`} />

        <linearGradient id={small1Gradient} x1="440.47" y1="697.03" x2="495.31" y2="697.03" href={`#${mainGradient}`} />

        <linearGradient id={small2Gradient} x1="465.36" y1="715.86" x2="515.3" y2="715.86" href={`#${mainGradient}`} />

        <linearGradient id={small3Gradient} x1="516.17" y1="740.55" x2="526.11" y2="740.55" href={`#${mainGradient}`} />

        <linearGradient id={centerGradient} x1="434.42" y1="451.78" x2="624.13" y2="451.78" href={`#${mainGradient}`} />

        {/* HER ORİJİNAL PATH İÇİN ANİMASYON MASKESİ */}

        {shouldAnimate &&
          PATHS.map((path, index) => (
            <mask key={index} id={`${id}-mask-${index}`} maskUnits="userSpaceOnUse" x="240" y="190" width="600" height="600">
              <rect x="240" y="190" width="600" height="600" fill="black" />

              {path.reveal === "wipe" ? (
                <motion.rect
                  x={path.wipe.x}
                  width={path.wipe.width}
                  fill="white"
                  variants={{
                    hidden: {
                      y: path.wipe.direction === "up" ? path.wipe.y + path.wipe.height : path.wipe.y,
                      height: 0,
                      opacity: 0,
                    },

                    visible: {
                      y: path.wipe.y,
                      height: path.wipe.height,
                      opacity: 1,
                    },

                    hover: {
                      y: path.wipe.direction === "up" ? [path.wipe.y + path.wipe.height, path.wipe.y] : path.wipe.y,

                      height: [0, path.wipe.height],
                      opacity: [0, 1],
                    },
                  }}
                />
              ) : (
                <motion.path
                  d={path.d}
                  fill="none"
                  stroke="white"
                  strokeWidth={110}
                  strokeLinecap="butt"
                  strokeLinejoin="round"
                  variants={maskVariants}
                  transition={{
                    pathLength: {
                      duration: drawDuration,
                      delay: path.delay ?? 0,
                      ease: [0.22, 1, 0.36, 1],
                    },

                    opacity: {
                      duration: 0,
                      delay: path.delay ?? 0,
                    },

                    visibility: {
                      duration: 0,
                      delay: path.delay ?? 0,
                    },
                  }}
                />
              )}
            </mask>
          ))}
      </defs>

      {PATHS.map((path, index) => {
        const fill = gradients[path.gradient];

        /*
          Animasyon istemiyorsak doğrudan gerçek SVG path'i.
          Arada motion/stroke/mask hiçbir şey yok.
        */
        if (!shouldAnimate) {
          return <path key={index} d={path.d} fill={fill} />;
        }

        /*
          Buradaki path tamamen ORİJİNAL logo.

          stroke yok.
          opacity hilesi yok.
          scale yok.
          geometri değişmiyor.

          Sadece mask tarafından görünür hale getiriliyor.
        */
        return <path key={index} d={path.d} fill={fill} mask={`url(#${id}-mask-${index})`} />;
      })}
    </motion.svg>
  );
}
